/*
 * mst_$lookup_object - locate a named object for mapping and check rights
 *
 * Original address: 0x00E43CBE (Ghidra mst_$lookup_object; module-local, no
 * SAU2 map symbol)
 * Size: 338 bytes (0x00E43CBE .. 0x00E43E0F)
 * Generated by: Claude Opus 5.5
 *
 * Caller: mst_$alloc_segs' named-UID path (0x00E4326C), with A5 = 0xE7CF0C
 * (MST_UNWIRED) loaded by its MST_ callers; this routine reads the rights
 * table at (0x38,A5).
 *
 * Frame (link.w A6,-0x4c; D2/A2-A3 saved):
 *   (0x08,A6) uid         copied to (-0x48,A6)
 *   (0x0C,A6) prot        word (D2w)
 *   (0x0E,A6) area_size   longword, FILE_$CHECK_PROT's slot argument
 *   (0x12,A6) location    longword out (A3)
 *   (0x16,A6) obj_length  longword out
 *   (0x1A,A6) status      (A2)
 *   (-0x4C) rights word, (-0x4A) FILE_$CHECK_PROT's rights out,
 *   (-0x40) the 0x18-byte common attributes, (-0x28) the 0x20-byte object
 *   location record (uid at -0x20, +0x10 at -0x18, +0x14 at -0x14, +0x1C at
 *   -0x0C, flags at -0x0B)
 *
 * Blocks:
 *   0x00E43CD2-0x00E43CE2  uid copy; a zero high half: not found
 *   0x00E43CE6-0x00E43CEC  rights = mst_$prot_rights[prot & 7]
 *   0x00E43CF2-0x00E43D2A  AST_$GET_COMMON_ATTRIBUTES(&loc, 2, &attr,
 *                          status); 0xF0001 -> not found, any other error
 *                          gets bit 31 set
 *   0x00E43D2E-0x00E43D46  attr bit 1 of byte 3 and (prot & 0x14) == 4:
 *                          status_$file_volume_has_been_mounted_read_only
 *   0x00E43D4A-0x00E43D60  *location = 0; local: low byte = loc byte 0x1C
 *   0x00E43D62-0x00E43D8E  remote: NETWORK_$INSTALL_NET(loc.loc_info,
 *                          location, status) (error: bit 31 set, return);
 *                          bit 31 set, low 20 bits = loc.node
 *   0x00E43D90-0x00E43DA2  *obj_length = attr.length; sub_type 3: done
 *   0x00E43DA4-0x00E43E00  FILE_$CHECK_PROT(&uid, rights, area_size, FALSE,
 *                          0, &rights_out, status); ACL 0x230001/2/4 and
 *                          0xF0001 become MST 0x40008/9/B and 0x40001
 *
 * Quirks reproduced:
 *   - The local arm keeps bit 31 of a location it has just cleared
 *     (`andi.l #0x80000000` then `or.l`).
 *   - The read-only refusal (0xF0016) is returned unflagged; the AST and
 *     network errors get bit 31.
 *   - FILE_$CHECK_PROT's result and rights word are ignored.
 */

#include "mst/mst_internal.h"
#include "ast/ast.h"
#include "file/file.h"
#include "network/network.h"
#include "acl/acl.h"

/* AST_$GET_COMMON_ATTRIBUTES flags (`move.w #0x2,-(SP)` 0x00E43D0C) */
#define MST_LOOKUP_ATTR_FLAGS       2

/* prot bits tested against the read-only volume flag (0x00E43D36-0x00E43D3A) */
#define MST_LOOKUP_PROT_WRITE_MASK  0x14
#define MST_LOOKUP_PROT_WRITE       0x04

/* attr.sub_type of an object whose rights are not checked (0x00E43D9E) */
#define MST_LOOKUP_NO_CHECK_TYPE    3

void mst_$lookup_object(uid_t *uid, uint16_t prot, uint32_t area_size,
                        uint32_t *location, uint32_t *obj_length,
                        status_$t *status)
{
    uid_t               uid_copy;       /* (-0x48,A6) */
    uint16_t            rights;         /* (-0x4C,A6) */
    uint16_t            rights_out;     /* (-0x4A,A6) */
    ast_$common_attr_t  attr;           /* (-0x40,A6) */
    file_$obj_loc_t     loc;            /* (-0x28,A6) */
    status_$t           st;

    /* 0x00E43CD2-0x00E43CE2 */
    uid_copy = *uid;
    if (uid_copy.high == 0) {
        *status = status_$mst_object_not_found;
        return;
    }

    /* 0x00E43CE6-0x00E43CEC */
    rights = mst_$prot_rights[prot & 7];

    /* 0x00E43CF2-0x00E43D2A */
    loc.uid = uid_copy;
    loc.flags &= ~0x40;                         /* bclr.b #0x6,(-0xb,A6) */
    AST_$GET_COMMON_ATTRIBUTES(&loc, MST_LOOKUP_ATTR_FLAGS, &attr, status);
    st = *status;
    if (st != status_$ok) {
        if (st == status_$file_object_not_found) {
            *status = status_$mst_object_not_found;
        } else {
            *status |= (status_$t)0x80000000;   /* bset.b #0x7,(A2) */
        }
        return;
    }

    /* 0x00E43D2E-0x00E43D46 */
    if ((attr.attr_flags_lo & 0x02) != 0 &&
        (prot & MST_LOOKUP_PROT_WRITE_MASK) == MST_LOOKUP_PROT_WRITE) {
        *status = status_$file_volume_has_been_mounted_read_only;
        return;
    }

    /* 0x00E43D4A-0x00E43D8E */
    *location = 0;
    if (loc.flags >= 0) {
        *location = (*location & 0x80000000u) | (uint8_t)loc.rights_bits;
    } else {
        NETWORK_$INSTALL_NET(loc.loc_info, location, status);
        if (*status != status_$ok) {
            *status |= (status_$t)0x80000000;   /* bset.b #0x7,(A2) */
            return;
        }
        *location |= 0x80000000u;               /* bset.b #0x7,(A3) */
        *location &= 0xFFF00000u;
        *location |= loc.node;
    }

    /* 0x00E43D90-0x00E43DA2 */
    *obj_length = attr.length;
    if (attr.sub_type == MST_LOOKUP_NO_CHECK_TYPE) {
        return;
    }

    /* 0x00E43DA4-0x00E43E00 */
    (void)FILE_$CHECK_PROT(&uid_copy, rights, area_size, 0, 0, &rights_out,
                           status);
    st = *status;
    if (st == status_$ok) {
        return;
    }
    if (st == status_$no_right_to_perform_operation) {
        *status = status_$mst_no_rights;
    } else if (st == status_$insufficient_rights_to_perform_operation) {
        *status = status_$mst_insufficient_rights;
    } else if (st == status_$acl_wrong_type) {
        *status = status_$mst_wrong_type;
    } else if (st == status_$file_object_not_found) {
        *status = status_$mst_object_not_found;
    }
}
